const TIME_LIMIT: int = 1924;
const OPENING_BUFFER: int = 120;
const TH15_BIG_BALL: int = 640; // Source type18; approved modern-catalog alias.

async sub phantom() {
    set_invuln(65535);
    set_hitbox(8fx);   // st06:1050, ordinary circle: 16/2.
    set_hurtbox(14fx); // st06:1049: 28/2.
    var cx: fx = $self_x;
    var cy: fx = $self_y;
    var phase: int = rand(65536); // 1055 RANDRAD, independently per enemy.
    // 1055-1058: REL circle, omega=2deg/tick, radius 0->16 over 180 ticks.
    // ABS stays at birth. Pre-position the next integrated point via velocity.
    // Approved synthetic death at age260 (80+180), just before source exit.
    for age in 0..260 {
        var t: int = age+1;
        var r: fx = 16fx;
        if t < 180 { r = 16fx*t/180; }
        var a: angle = (phase+t*65536/180) as angle;
        var nx: fx = cx+r*cos(a);
        var ny: fx = cy+r*sin(a);
        move_vel_xy(0, nx-$self_x, ny-$self_y, EASE_LINEAR);
        wait(1);
    }
    // 1069-1097: fixed downward fan N=1, M=1/3/5/7 speed layers.
    // No additional aiming/random draws; q outer order is source order.
    var rank: int = global(GVAR_RANK);
    var layers: int = 1;
    var first: fx = 2fx;
    if rank == 1 { layers = 3; first = 4fx; }
    if rank == 2 { layers = 5; first = 5fx; }
    if rank == 3 { layers = 7; first = 6fx; }
    for q in 0..layers {
        var v: fx = first;
        if layers > 1 { v = first+(1fx-first)*q/(layers-1); }
        // EX ANIM a=1: retain initial -4*velocity displacement;
        // approved omission of its birth animation/protection/slowdown stage.
        _ = fire(TH15_BIG_BALL, 2, $self_x, $self_y-4fx*v, v, 90deg, none, none);
    }
    // Synthetic one-shot death replaces original player-triggered callback;
    // source 1059+ escape is unreachable after this chosen death.
    drop_clear();
    die();
}

async sub pattern() {
    wait(OPENING_BUFFER);
    // Source 699 entry = logical source0; 702 wait120 is retained in addition
    // to the card opening buffer. All four creates in source are enmCreate,
    // not enmCreateM, so no mirror flag is introduced.
    wait(120);
    var x: fx = -160fx;
    for wave in 0..4 {
        for i in 0..32 {
            // 708/718/728/738: distinct signed random X then Y draws.
            var rx: fx = (rand(65536)-32768) as fx / 32768;
            var ry: fx = (rand(65536)-32768) as fx / 32768;
            _ = spawn_enemy(x+rx*16fx, 128fx+ry*32fx, 170, 0, 0, 0, phantom);
            if wave%2 == 0 { x = x+10fx; }
            else { x = x-10fx; }
            wait(3);
        }
        if wave < 3 { wait(180); }
    }
    // Source main's following wait400/clear is outside the selected entry;
    // the supplied 1800-frame synthetic window leaves the slow tail intact.
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}
sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
